'use strict';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),safe=u=>/^https?:\/\//.test(u||'')?esc(u):'#';
let papers=[],coverage={},journals=[],selectedInstitution='',filtered=[],limit=24,statsRows=[];
const labels={search:'Search',family:'Family',journal:'Journal',domain:'Area',method:'AI approach',disease:'Disease focus',type:'Article type',affiliation:'Institution evidence',curation_level:'Record detail'};
const textOf=x=>typeof x==='string'?x:x?.name||x?.full_address||'';
const authorNames=p=>(p.authors||[]).map(textOf).filter(Boolean);
function options(id,values){for(const v of [...new Set(values.filter(Boolean))].sort())$(id).add(new Option(v,v));}
function reset(){for(const id of Object.keys(labels))$(id).value='';selectedInstitution='';limit=24;render();}
function selected(p,omit=''){
 const q=$('search').value.trim().toLowerCase();
 return (!q||JSON.stringify(p).toLowerCase().includes(q))&&(!selectedInstitution||p.first_institution===selectedInstitution)&&Object.keys(labels).filter(k=>k!=='search'&&k!==omit).every(k=>{const v=$(k).value;if(!v)return true;return k==='domain'?p.domains.includes(v):k==='method'?p.methods.includes(v):k==='disease'?p.diseases.includes(v):k==='type'?p.article_type===v:k==='affiliation'?p.institution_verified:p[k]===v;});
}
function activeFilters(){const chips=[];for(const [id,label] of Object.entries(labels)){const el=$(id);if(!el.value)continue;const val=id==='affiliation'?'Verified first institution':el.value;chips.push(`<button class="filter-chip" data-clear="${id}" aria-label="Clear ${esc(label)} filter">${label}: ${esc(val)} ×</button>`);}if(selectedInstitution)chips.push(`<button class="filter-chip" data-clear="institution" aria-label="Clear selected institution">Institution: ${esc(selectedInstitution)} ×</button>`);$('activeFilters').hidden=!chips.length;$('activeFilters').innerHTML=chips.length?chips.join('')+'<button class="clear-all" data-reset>Clear all filters</button>':'';}
function count(items,key){const map={};for(const p of items)for(const v of Array.isArray(p[key])?p[key]:[p[key]])if(v)map[v]=(map[v]||0)+1;return Object.entries(map).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));}
function bars(id,values,key,current){const max=Math.max(1,...values.map(x=>x[1]));$(id).innerHTML=values.map(([name,n])=>`<div class="bar-row"><button class="bar-label" data-chart="${key}" data-value="${esc(name)}" aria-pressed="${current===name}">${esc(name)}</button><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><strong>${n.toLocaleString()}</strong></div>`).join('')||'<p class="muted">No records in this selection.</p>';}
function analytics(){
 $('insightsScope').textContent=`${filtered.length.toLocaleString()} selected publications. Themes may overlap; patients, images and cells are not pooled.`;
 statsRows=[['Dimension','Category','Publications','Denominator','Percent','Counting rule']];
 // Show alternatives for a selected dimension so another option can be chosen without clearing it first.
 const journalBase=papers.filter(p=>selected(p,'journal')),domainBase=papers.filter(p=>selected(p,'domain')),methodBase=papers.filter(p=>selected(p,'method'));
 bars('journalBars',count(journalBase,'journal'),'journal',$('journal').value);bars('domainBars',count(domainBase,'domains'),'domain',$('domain').value);bars('methodBars',count(methodBase,'methods'),'method',$('method').value);
 const mapped=filtered.filter(p=>p.institution_verified);$('institutionCoverage').textContent=`${mapped.length.toLocaleString()} / ${filtered.length.toLocaleString()} selected papers have a verified, named first institution. One first author’s first institution per paper; exact reported organizations, not all coauthor affiliations.`;
 const institutionBase=papers.filter(p=>{const keep=selectedInstitution;selectedInstitution='';try{return selected(p)&&p.institution_verified;}finally{selectedInstitution=keep;}});
 bars('institutionBars',count(institutionBase,'first_institution').slice(0,40),'institution',selectedInstitution);
 const months={};filtered.forEach(p=>{const k=p.date.slice(0,7);months[k]=(months[k]||0)+1});const max=Math.max(1,...Object.values(months));$('monthChart').innerHTML=Array.from({length:10},(_,i)=>{const key='2026-'+String(i+1).padStart(2,'0'),n=months[key]||0;return `<div class="month-row"><span>${new Date(2026,i,1).toLocaleDateString('en',{month:'short'})}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><span>${n}</span></div>`}).join('');
 for(const [name,key]of [['Journal','journal'],['Research area','domains'],['AI approach','methods'],['First institution','first_institution'],['Article type','article_type'],['Disease tag','diseases']])for(const [v,n]of count(name==='First institution'?mapped:filtered,key))statsRows.push([name,v,n,filtered.length,filtered.length?(100*n/filtered.length).toFixed(1):0,name==='First institution'?'Verified first institution only':'Publication; multi-label dimensions may overlap']);
}
function designStatistics(){
 bars('diseaseBars',count(papers.filter(p=>selected(p,'disease')),'diseases'),'disease',$('disease').value);
 const designs=[['collection','Prospective data collection'],['validation','Prospective validation'],['patient_rct','Patient randomized controlled trial'],['reader','Reader / clinician experiment']];
 $('designTable').innerHTML=designs.map(([key,label])=>{const yes=filtered.filter(p=>p.study_design[key]===true).length,no=filtered.filter(p=>p.study_design[key]===false).length,unknown=filtered.length-yes-no;statsRows.push(['Study design',label+' — present',yes,filtered.length,filtered.length?(100*yes/filtered.length).toFixed(1):0,'Curated design labels only; unassessed excluded from negative counts']);return `<tr><td>${label}</td><td>${yes}</td><td>${no}</td><td>${unknown}</td></tr>`;}).join('');
 const evidence=[['Linked code statement',p=>p.code_links.length>0],['Linked data statement',p=>p.data_links.length>0],['Named datasets extracted',p=>p.datasets.length>0],['Experimental counts extracted',p=>p.experiment_scale.length>0],['Verified first institution',p=>p.institution_verified]];
 $('resourceStats').innerHTML='<table><thead><tr><th>Evidence field</th><th>With</th><th>Without</th></tr></thead><tbody>'+evidence.map(([name,fn])=>{const n=filtered.filter(fn).length;statsRows.push(['Resource evidence',name,n,filtered.length,filtered.length?(100*n/filtered.length).toFixed(1):0,'Field populated; does not imply public data/code availability']);return `<tr><td>${name}</td><td>${n}</td><td>${filtered.length-n}</td></tr>`;}).join('')+'</tbody></table><p class="source-note">Without a linked/extracted field does not mean the study lacked data or code.</p>';
}
function scaleLabel(p){if(!p.experiment_scale?.length)return /review|perspective|protocol/i.test(p.article_type)?'See review / protocol scope':'Not yet extracted from source evidence';return p.experiment_scale.slice(0,2).map(s=>`${s.value??s.n??''} ${s.unit||''}`).join(' · ');}
function dataLabel(p){return p.datasets?.length?p.datasets.slice(0,2).map(textOf).join(' · '):p.data_links.length?'Availability statement linked':'Check original data statement';}
function render(){
 filtered=papers.filter(p=>selected(p));const sort=$('sort').value;filtered.sort(sort==='title'?(a,b)=>a.title.localeCompare(b.title):sort==='journal'?(a,b)=>a.journal.localeCompare(b.journal)||b.date.localeCompare(a.date):sort==='oldest'?(a,b)=>a.date.localeCompare(b.date):(a,b)=>b.date.localeCompare(a.date)||a.title.localeCompare(b.title));activeFilters();
 $('resultsCount').textContent=`${filtered.length.toLocaleString()} papers · showing ${Math.min(limit,filtered.length).toLocaleString()} · snapshot ${coverage.snapshot_date}`;
 $('export').disabled=!filtered.length;$('exportStats').disabled=!filtered.length;
 $('papers').innerHTML=filtered.slice(0,limit).map(p=>`<article class="paper"><div class="paper-body"><div class="paper-meta"><span class="journal-badge">${esc(p.journal)}</span><span>${esc(p.date)}</span></div><button class="paper-title" data-paper="${esc(p.id)}">${esc(p.title)}</button><p class="authors">${esc(authorNames(p).slice(0,3).join(', ')||p.first_author)}${authorNames(p).length>3?' et al.':''}</p><p class="institution" title="${esc(p.first_affiliation)}">${p.institution_verified?esc(p.first_institution):'First institution not verified'}</p><p class="paper-question">${p.problem_is_excerpt?'“':''}${esc(p.research_problem)}${p.problem_is_excerpt?'” <span class="excerpt-label">— source excerpt</span>':''}</p><div class="tags">${p.domains.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="tag">${esc(p.article_type)}</span></div><div class="paper-facts"><div><strong>${p.scale_status==='source_extracted'?'Reported counts · extracted':'Experimental scale'}</strong><span>${esc(scaleLabel(p))}</span></div><div><strong>Data sources</strong><span>${esc(dataLabel(p))}</span></div></div></div><div class="paper-footer"><span>${p.curation_level==='curated'?'Curated analysis':'Source-extracted record'} · ${p.review_level==='fulltext'?'Full-text evidence':'Abstract evidence'}</span><button data-paper="${esc(p.id)}">Explore evidence ↗</button></div></article>`).join('')||'<div class="empty">No papers match this selection.<br><button data-reset>Clear all filters</button></div>';
 $('more').hidden=filtered.length<=limit;analytics();designStatistics();
}
function listLinks(values){return values.map(x=>`<li><a href="${safe(x.url)}" target="_blank" rel="noopener">${esc(x.label||x.url)} ↗</a></li>`).join('');}
function detail(id){const p=papers.find(x=>x.id===id);if(!p)return;const firstAff=p.first_affiliation||'Not reported in accessible metadata';
 $('paperDetail').innerHTML=`<div class="detail-meta">${esc(p.journal)} · ${esc(p.date)} · ${esc(p.article_type)}</div><h2 id="detailTitle">${esc(p.title)}</h2><p>${esc(authorNames(p).join(', ')||p.first_author)}</p><div class="detail-links"><a href="${safe(p.url)}" target="_blank" rel="noopener">Original paper ↗</a><a href="https://doi.org/${esc(p.doi)}" target="_blank" rel="noopener">DOI ↗</a></div><div class="detail-facts"><div><strong>Journal family</strong>${esc(p.family)}</div><div><strong>Evidence level</strong>${p.review_level==='fulltext'?'Full-text evidence':'Accessible abstract and source metadata'}</div><div><strong>First author</strong>${esc(p.first_author||'Not available')}</div><div><strong>First institution</strong>${esc(p.first_institution||'Not verified as a named organization')}</div></div><h3>${p.problem_is_excerpt?'Objective · source excerpt':'Research question'}</h3><p>${p.problem_is_excerpt?'“':''}${esc(p.research_problem)}${p.problem_is_excerpt?'”':''}</p><h3>Study design evidence</h3><p>${[['collection','Prospective data collection'],['validation','Prospective validation'],['patient_rct','Patient RCT'],['reader','Reader / clinician experiment']].map(([key,label])=>esc(label)+': '+(p.study_design[key]===true?'Present':p.study_design[key]===false?'Absent':'Not assessed')).join('<br>')}</p><h3>AI approach</h3><p>${esc(p.ai_method)}</p>${p.study_summary?`<h3>What the study found</h3><p>${esc(p.study_summary)}</p>`:''}<h3>Experimental scale</h3>${p.experiment_scale?.length?`<ul class="data-list">${p.experiment_scale.map(s=>`<li><strong>${esc(s.value??s.n??'')} ${esc(s.unit||'')}</strong>${s.context?' — '+esc(s.context):''}</li>`).join('')}</ul>`:'<p>No quantitative scale has been verified from accessible evidence. Reviews and protocols do not imply a new patient cohort.</p>'}<p class="source-note">${p.scale_status==='source_extracted'?'Counts were extracted from source evidence. Their cohort roles are not all manually resolved; follow the original methods before treating a value as a participant denominator.':'Different units and cohort roles are shown separately. No across-paper sample totals are computed.'}</p><h3>Datasets &amp; access</h3>${p.datasets?.length?`<ul class="data-list">${p.datasets.map(d=>`<li><strong>${esc(d.name||'Dataset')}</strong>${d.source?' — '+esc(d.source):''}${d.access?'<br>'+esc(d.access):''}${d.url?`<br><a href="${safe(d.url)}" target="_blank" rel="noopener">Dataset / availability source ↗</a>`:''}</li>`).join('')}</ul>`:'<p>Refer to the original availability statement. No dataset identity or openness is inferred from an absent field.</p>'}${p.data_links.length?'<ul class="data-list">'+listLinks(p.data_links)+'</ul>':''}<h3>Code &amp; resources</h3>${p.code_links.length?'<ul class="data-list">'+listLinks(p.code_links)+'</ul>':'<p>No author-code link verified from the availability statement.</p>'}<h3>Authors &amp; institutions</h3><p><strong>First author’s first affiliation:</strong><br>${esc(firstAff)}</p><details><summary>All source-reported affiliations (${p.all_affiliations.length})</summary><ul class="data-list">${p.all_affiliations.map(a=>`<li>${esc(textOf(a))}${a.authors?'<br>'+esc(a.authors):''}</li>`).join('')}</ul></details><h3>Why it is in scope</h3><p>${esc(p.scope_reason)}</p><h3>Evidence &amp; provenance</h3><ul class="data-list">${listLinks(p.evidence_links)}</ul><p class="source-note">${p.curation_level==='curated'?'This record contains a curated interpretation of the source evidence.':'This record uses source extraction and an explicit AI–biomedical scope screen. Extracted fields are not presented as fully curated experimental conclusions.'} ${p.review_level==='fulltext'?'Relevant full text was available.':'Accessible evidence may omit details in the full methods.'}</p>`;
 $('paperDialog').showModal();history.replaceState(null,'',location.pathname+location.search+'#paper='+encodeURIComponent(id));
}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>{let s=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+\-@\r\t]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n');}
function download(name,body,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([body],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function init(){try{
 [papers,coverage,journals]=await Promise.all(['papers','coverage','journals'].map(n=>fetch('data/'+n+'.json').then(r=>{if(!r.ok)throw Error('Could not load '+n);return r.json()})));
 options('family',papers.map(p=>p.family));options('journal',papers.map(p=>p.journal));options('domain',papers.flatMap(p=>p.domains));options('method',papers.flatMap(p=>p.methods));options('type',papers.map(p=>p.article_type));options('disease',papers.flatMap(p=>p.diseases));
 $('metrics').innerHTML=[[papers.length,'AI × biomedical papers'],[new Set(papers.map(p=>p.journal)).size,'Journals represented'],[papers.filter(p=>p.institution_verified).length,'Papers with mapped first institution'],[papers.filter(p=>p.code_links.length||p.data_links.length).length,'Linked data / code statements']].map(([n,l])=>`<div class="metric"><strong>${n.toLocaleString()}</strong><span>${l}</span></div>`).join('');
 $('coverageSummary').textContent=`Snapshot: ${coverage.snapshot_date}. ${coverage.journals_in_scope} journals are in scope; ${coverage.metadata_records.toLocaleString()} dated DOI records were retrieved and ${coverage.recall_candidates.toLocaleString()} records entered candidate screening. ${coverage.indexed.toLocaleString()} are currently indexed after an AI–biomedical scope screen. ${coverage.curated.toLocaleString()} contain curated analyses; ${coverage.source_extracted.toLocaleString()} use labeled source extraction. The ledger distinguishes screened and pending candidates. Keyword recall is not an exhaustive full-text census.`;
 $('coverageTable').innerHTML=coverage.ledger.map(j=>`<tr><td><a href="${safe(j.url)}" target="_blank" rel="noopener">${esc(j.name)} ↗</a></td><td>${j.metadata_records==null?'—':j.metadata_records.toLocaleString()}</td><td>${j.candidates}</td><td>${j.reviewed}</td><td>${j.indexed}</td><td>${j.pending}</td><td>${j.metadata_status==='open_for_submissions'?'Open for submissions; no indexed journal record':j.pending?'Screening in progress':'Recall candidates screened'}${j.source_note?'<br>'+esc(j.source_note):''}</td></tr>`).join('');
 for(const id of Object.keys(labels))$(id).addEventListener(id==='search'?'input':'change',()=>{limit=24;render()});$('sort').onchange=render;$('filters').onsubmit=e=>e.preventDefault();$('filters').onreset=e=>{e.preventDefault();reset()};
 $('activeFilters').onclick=e=>{const b=e.target.closest('[data-clear],[data-reset]');if(!b)return;if(b.hasAttribute('data-reset'))reset();else{if(b.dataset.clear==='institution')selectedInstitution='';else $(b.dataset.clear).value='';limit=24;render()}};
 $('papers').onclick=e=>{const b=e.target.closest('[data-paper],[data-reset]');if(!b)return;if(b.hasAttribute('data-reset'))reset();else detail(b.dataset.paper)};
 $('insights').onclick=e=>{const b=e.target.closest('[data-chart]');if(!b)return;const key=b.dataset.chart,value=b.dataset.value;if(key==='institution')selectedInstitution=selectedInstitution===value?'':value;else $(key).value=$(key).value===value?'':value;limit=24;render();$('catalogue').scrollIntoView()};
 $('more').onclick=()=>{limit+=24;render()};$('closeDialog').onclick=()=>$('paperDialog').close();$('paperDialog').addEventListener('close',()=>history.replaceState(null,'',location.pathname+location.search+'#catalogue'));
 $('export').onclick=()=>{const cols=['doi','title','date','journal','family','article_type','research_problem','ai_method','first_author','first_institution','experiment_scale','datasets','review_level','curation_level','url'];download('medicalai-nature-filtered.csv',csv([cols,...filtered.map(p=>cols.map(c=>p[c]))]),'text/csv;charset=utf-8;')};$('exportStats').onclick=()=>download('medicalai-nature-statistics.csv',csv(statsRows),'text/csv;charset=utf-8;');
 render();if(location.hash.startsWith('#paper='))detail(decodeURIComponent(location.hash.slice(7)));
 }catch(error){$('resultsCount').textContent='Unable to load the catalogue. Please reload or download the open data.';console.error(error)}}
init();
